const v = $('loop-by-pending-video').item.json;
const durMin = (v.duracao_segundos || 0) / 60;
let preferLength = [1];
if (durMin >= 10) preferLength = [1, 2, 3];
else if (durMin >= 5) preferLength = [1, 2];
else preferLength = [1];

const KW = {
  financas: 'dinheiro, investimentos, renda extra, juros compostos, liberdade financeira, dica pratica de financas, erro financeiro comum',
  fitness:  'treino, hipertrofia, dieta, emagrecimento, dica pratica de treino, erro comum na academia, nutricao',
  mindset:  'mentalidade, disciplina, habitos, motivacao, virada de chave, desenvolvimento pessoal',
  coach:    'produtividade, carreira, lideranca, alta performance, rotina, foco',
  copa:     'gol, melhores momentos, lance decisivo, defesa dificil, jogada genial, comemoracao'
};
const nicho = String(v.nicho || '').toLowerCase();
const keywords = KW[nicho] || 'momento de maior impacto, frase forte, insight pratico, historia marcante';
const projectName = ('[' + nicho + '] ' + String(v.titulo_original || '').substring(0, 60)).trim();

return [{ json: { ...v, preferLength, keywords, project_name: projectName } }];

// Avalia saida do node Vizard (createClips).
// Sucesso: { code: 2000, projectId }. Erro: { error: 'Vizard API error 4003 ...' } na saida principal (continueOnFail).
const videoId = $('loop-by-pending-video').item.json.id;
const res = $input.first().json || {};

let outcome, code = null, projectId = null, friendly = '';

if (res.error) {
  const msg = String(res.error);
  const m = msg.match(/Vizard API error (-?\d+)/i);
  code = m ? Number(m[1]) : null;
  const RETRY = new Set([1000, 4003, 4008]);
  const isHttpTransient = /ECONN|ETIMEDOUT|ENOTFOUND|timeout|socket|503|502|504/i.test(msg);
  outcome = (code !== null && RETRY.has(code)) || (code === null && isHttpTransient) ? 'retry' : 'perm';
  friendly = msg;
} else {
  code = Number(res.code);
  projectId = res.projectId || null;
  if (code === 2000 && projectId) {
    outcome = 'ok';
    friendly = 'Project created';
  } else if (code === 2000) {
    outcome = 'perm';
    friendly = 'Vizard retornou 2000 sem projectId';
  } else {
    outcome = 'perm';
    friendly = 'Codigo inesperado ' + code;
  }
}

const erroMsg = outcome === 'ok' ? null : String((code !== null ? code + ': ' : '') + friendly).substring(0, 500).replace(/'/g, '');

return [{ json: {
  video_pendente_id: videoId,
  outcome,
  vizard_code: code,
  vizard_project_id: projectId,
  erro_mensagem: erroMsg
} }];

